import { refreshCsrfToken } from '../data/session'
import { currentUser, loadMyRoles } from '../data/user'
import { diskresiPillClass, STATE_ALLOW_EDIT } from '../data/suratDiskresiStatus'
import { notifyError, notifySuccess } from '../composables/toast'
import { openAttachment, openPdf } from '../composables/pdfViewer'
import { canUseCamera, capturePhoto } from '../composables/cameraCapture'
import { useBackNavigation } from '../composables/useBackNavigation'
import SelectMenu from '../components/SelectMenu.vue'

const route = useRoute()
const { backTarget, backLabel } = useBackNavigation({ name: 'Diskresi' }, 'Diskresi')
const name = computed(() => route.params.name)

const inputClass =
	'min-h-[44px] w-full rounded-md border border-ui-line-gray-300 bg-ui-surface px-3 py-2 text-base text-ui-ink-gray-800 outline-none transition focus:border-primary focus:ring-2 focus:ring-inset focus:ring-primary/30 md:min-h-0'

const doc = createResource({
	url: 'frappe.client.get',
	makeParams() {
		return { doctype: 'Surat Diskresi', name: name.value }
	},
	auto: false,
})

const banner = ref('')

// ---- Meta doctype → section → kolom → field --------------------------------
const metaFields = ref([])
const metaError = ref('')
const form = reactive({})

async function loadMeta() {
	try {
		const res = await fetch(
			`/api/method/frappe.desk.form.load.getdoctype?doctype=${encodeURIComponent(
				'Surat Diskresi'
			)}`,
			{ method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } }
		)
		if (!res.ok) throw new Error(`HTTP ${res.status}`)
		const json = await res.json()
		const docs = json.docs || json.message?.docs || []
		const dt = docs.find((x) => x.name === 'Surat Diskresi') || docs[0]
		metaFields.value = (dt && dt.fields) || []
	} catch (e) {
		metaError.value = e.message || String(e)
	}
}

// Nilai "kosong" ala frappe.is_null: null/undefined/'' (0 TIDAK dianggap kosong).
function isNullVal(v) {
	return v == null || v === ''
}

// Evaluasi depends_on Frappe (akses form reaktif + shim frappe.session —
// dipakai depends_on approval_preview_pdf: frappe.session.user === "Administrator").
function evalCondition(expr) {
	if (!expr) return true
	try {
		const code = String(expr).replace(/^eval:/, '')
		const frappeShim = { session: { user: currentUser.user || '' } }
		const in_list = (list, item) => Array.isArray(list) && list.includes(item)
		const cint = (v) => parseInt(v, 10) || 0
		const cstr = (v) => (v == null ? '' : String(v))
		const flt = (v) => parseFloat(v) || 0
		// eslint-disable-next-line no-new-func
		return !!new Function(
			'doc',
			'frappe',
			'in_list',
			'cint',
			'cstr',
			'flt',
			`return (${code})`
		)(form, frappeShim, in_list, cint, cstr, flt)
	} catch (e) {
		return true
	}
}

// Field yang tidak ditampilkan sebagai baris detail di portal.
// `approval_preview_pdf` diwakili tombol "Download PDF" di action bar bawah.
const FIELDS_HIDDEN_IN_PORTAL = new Set(['approval_preview_pdf'])

// Susun section → kolom → field persis urutan meta (doctype ini tanpa Tab Break).
const sections = computed(() => {
	const secs = []
	let curSection = null
	let curCol = null
	for (const f of metaFields.value) {
		const ft = f.fieldtype
		if (ft === 'Section Break') {
			curCol = []
			curSection = { label: f.label || '', depends_on: f.depends_on, columns: [curCol] }
			secs.push(curSection)
			continue
		}
		if (ft === 'Column Break') {
			if (!curSection) {
				curCol = []
				curSection = { label: '', columns: [curCol] }
				secs.push(curSection)
			} else {
				curCol = []
				curSection.columns.push(curCol)
			}
			continue
		}
		if (['HTML', 'Button', 'Heading', 'Fold', 'Image', 'Barcode', 'Table'].includes(ft))
			continue
		if (f.hidden || FIELDS_HIDDEN_IN_PORTAL.has(f.fieldname)) continue
		// Meniru frappe.perm.get_field_display_status: field read_only yang
		// KOSONG disembunyikan; read_only yang ADA isinya tetap ditampilkan.
		if (f.read_only && isNullVal(form[f.fieldname])) continue
		if (f.depends_on && !evalCondition(f.depends_on)) continue
		if (!curSection) {
			curCol = []
			curSection = { label: '', columns: [curCol] }
			secs.push(curSection)
		}
		curCol.push(f)
	}
	return secs
		.filter((s) => evalCondition(s.depends_on))
		.map((s) => ({ ...s, columns: s.columns.filter((c) => c.length) }))
		.filter((s) => s.columns.length)
})

// ---- Mode baca/edit (mengikuti Allow Edit workflow per state) ---------------
const editMode = ref(false)
const canEdit = computed(() => {
	const roles = currentUser.roles || []
	if (currentUser.user === 'Administrator') return true
	const allowed = STATE_ALLOW_EDIT[doc.data?.status] || []
	return allowed.some((r) => roles.includes(r))
})

// read_only meta + read_only_depends_on; di luar edit mode semua terkunci.
function isFieldReadOnly(field) {
	if (!editMode.value) return true
	if (field.read_only) return true
	return field.read_only_depends_on ? evalCondition(field.read_only_depends_on) : false
}

function isTextarea(ft) {
	return ['Small Text', 'Text', 'Long Text'].includes(ft)
}
function selectOptions(field) {
	return String(field.options || '')
		.split('\n')
		.map((s) => s.trim())
		.filter(Boolean)
}

// Angsuran Baru dihitung live saat mengedit Nominal Pengurangan (meniru dialog
// desk); nilai final tetap dihitung ulang server saat Save.
function displayValue(field) {
	if (
		field.fieldname === 'angsuran_baru' &&
		editMode.value &&
		form.tipe_diskresi === 'Pengurangan Angsuran'
	) {
		return Math.max(0, Number(form.angsuran || 0) - Number(form.nominal_pengurangan || 0))
	}
	return form[field.fieldname]
}

// ---- Format helpers ---------------------------------------------------------
function currencyDisplay(v) {
	if (v === '' || v == null || Number.isNaN(Number(v))) return ''
	return `Rp ${new Intl.NumberFormat('id-ID', {
		minimumFractionDigits: 2,
		maximumFractionDigits: 2,
	}).format(Number(v))}`
}
function parseCurrency(str) {
	if (str == null) return ''
	const cleaned = String(str)
		.replace(/\./g, '')
		.replace(',', '.')
		.replace(/[^\d.]/g, '')
	if (cleaned === '') return ''
	const n = Number(cleaned)
	return Number.isNaN(n) ? '' : n
}
function onCurrencyBlur(field, e) {
	const n = parseCurrency(e.target.value)
	form[field.fieldname] = n
	e.target.value = currencyDisplay(n)
}
function formatDateDisplay(v) {
	if (!v) return ''
	const m = String(v).match(/^(\d{4})-(\d{2})-(\d{2})/)
	return m ? `${m[3]}-${m[2]}-${m[1]}` : String(v)
}
function fileName(url) {
	if (!url) return ''
	const clean = String(url).split('?')[0]
	return decodeURIComponent(clean.substring(clean.lastIndexOf('/') + 1)) || clean
}

// ---- Link / Dynamic Link dropdown -------------------------------------------
const openDropdown = ref('')
const linkSearch = ref('')
const linkResults = ref([])
const linkSearchLoading = ref(false)
let linkSearchTimer = null

// Doctype tujuan sebuah field Link/Dynamic Link. Dynamic Link: options = nama
// field yang menyimpan doctype (reference_doctype).
function linkTargetDoctype(field) {
	if (field.fieldtype === 'Dynamic Link') return form[field.options] || ''
	return field.options || ''
}

function toggleLinkDropdown(field) {
	if (openDropdown.value === field.fieldname) {
		openDropdown.value = ''
		return
	}
	openDropdown.value = field.fieldname
	linkSearch.value = ''
	fetchLinkResults(field, '')
}

async function fetchLinkResults(field, query) {
	linkSearchLoading.value = true
	linkResults.value = []
	try {
		// Tipe Diskresi → endpoint portal (master Kategori Diskresi hanya readable
		// System Manager; jenis difilter sesuai referensi, meniru validasi backend).
		if (field.fieldname === 'tipe_diskresi') {
			const params = new URLSearchParams({
				jenis: form.reference_doctype || 'Data Pengajuan',
			})
			const res = await fetch(
				`/api/method/juragan.api.portal.surat_diskresi.get_kategori_diskresi?${params.toString()}`,
				{ method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } }
			)
			const json = await res.json()
			const all = json.message || []
			const q = (query || '').toLowerCase()
			linkResults.value = q ? all.filter((x) => x.toLowerCase().includes(q)) : all
			return
		}
		const dt = linkTargetDoctype(field)
		if (!dt) {
			linkResults.value = []
			return
		}
		const params = new URLSearchParams({
			doctype: dt,
			fields: JSON.stringify(['name']),
			limit_page_length: '20',
			order_by: 'modified desc',
		})
		if (query) params.set('filters', JSON.stringify([['name', 'like', `%${query}%`]]))
		const res = await fetch(`/api/method/frappe.client.get_list?${params.toString()}`, {
			method: 'GET',
			credentials: 'include',
			headers: { Accept: 'application/json' },
		})
		const json = await res.json()
		linkResults.value = (json.message || []).map((r) => String(r.name))
	} catch (e) {
		linkResults.value = []
	} finally {
		linkSearchLoading.value = false
	}
}

function onLinkSearch(field) {
	clearTimeout(linkSearchTimer)
	linkSearchTimer = setTimeout(() => fetchLinkResults(field, linkSearch.value.trim()), 300)
}

function selectLink(field, value) {
	form[field.fieldname] = value
	openDropdown.value = ''
	// Ganti Referensi Doctype → kosongkan dokumen referensi & tipe (validasi jenis beda).
	if (field.fieldname === 'reference_doctype') {
		form.reference_name = ''
		form.tipe_diskresi = ''
	}
}

// ---- Upload Attach (file_pendukung) -----------------------------------------
// Tombol "Ambil Foto" hanya ditampilkan di dalam aplikasi native; di browser
// atribut `capture` diabaikan sehingga tombolnya mubazir (lihat cameraCapture.js).
const showCameraButton = canUseCamera()
const fileInput = ref(null)
const pendingAttachField = ref(null)
const uploadingField = ref('')
const MAX_FILE_MB = 3

function triggerFilePick(field) {
	pendingAttachField.value = field
	if (fileInput.value) {
		fileInput.value.value = ''
		fileInput.value.click()
	}
}

// Kamera dipicu input terpisah karena input file biasa selalu jatuh ke
// document picker di Android (lihat cameraCapture.js).
function triggerCameraPick(field) {
	capturePhoto().then((file) => uploadAttachFile(file, field))
}

async function onFileChange(e) {
	await uploadAttachFile(e.target.files && e.target.files[0], pendingAttachField.value)
}

async function uploadAttachFile(file, field) {
	if (!file || !field) return
	const ext = (file.name.split('.').pop() || '').toLowerCase()
	if (!['jpg', 'jpeg', 'png', 'pdf'].includes(ext)) {
		banner.value = 'Format file harus JPG, PNG, atau PDF.'
		return
	}
	if (file.size > MAX_FILE_MB * 1024 * 1024) {
		banner.value = `Ukuran file maksimal ${MAX_FILE_MB} MB.`
		return
	}
	uploadingField.value = field.fieldname
	try {
		const fd = new FormData()
		fd.append('file', file, file.name)
		fd.append('is_private', '1')
		fd.append('doctype', 'Surat Diskresi')
		fd.append('docname', name.value)
		const res = await fetch('/api/method/upload_file', {
			method: 'POST',
			credentials: 'include',
			headers: {
				Accept: 'application/json',
				'X-Frappe-CSRF-Token': window.csrf_token || '',
			},
			body: fd,
		})
		const json = await res.json().catch(() => ({}))
		if (!res.ok) throw new Error(frappeError(json) || `HTTP ${res.status}`)
		form[field.fieldname] = json.message.file_url
	} catch (err) {
		banner.value = err.message || String(err)
		notifyError(err, 'Gagal mengunggah file')
	} finally {
		uploadingField.value = ''
		pendingAttachField.value = null
	}
}

// ---- Save --------------------------------------------------------------------
const saving = ref(false)

function frappeError(json) {
	try {
		if (json && json._server_messages) {
			const arr = JSON.parse(json._server_messages)
			return arr
				.map((m) => {
					try {
						return JSON.parse(m).message
					} catch (e) {
						return m
					}
				})
				.join('\n')
		}
	} catch (e) {
		/* ignore */
	}
	return (json && (json.exception || json.message)) || ''
}

function syncFormFromDoc() {
	Object.assign(form, doc.data || {})
}

async function saveDocument() {
	saving.value = true
	banner.value = ''
	try {
		const payload = JSON.parse(JSON.stringify(form))
		payload.doctype = 'Surat Diskresi'
		payload.name = name.value
		const res = await fetch('/api/method/frappe.client.save', {
			method: 'POST',
			credentials: 'include',
			headers: {
				'Content-Type': 'application/json',
				Accept: 'application/json',
				'X-Frappe-CSRF-Token': window.csrf_token || '',
			},
			body: JSON.stringify({ doc: payload }),
		})
		const json = await res.json().catch(() => ({}))
		if (!res.ok) throw new Error(frappeError(json) || `HTTP ${res.status}`)
		await doc.fetch()
		syncFormFromDoc()
		editMode.value = false
		loadTransitions()
		notifySuccess('Perubahan berhasil disimpan.')
	} catch (e) {
		banner.value = e.message || String(e)
		notifyError(e, 'Gagal menyimpan')
	} finally {
		saving.value = false
	}
}

// ---- Download PDF -----------------------------------------------------------
// Tombol menggantikan field "Approval Preview PDF" (field-nya disembunyikan dari
// daftar detail, lihat FIELDS_HIDDEN_IN_PORTAL). Karena itu tombol HANYA muncul
// bila dokumen benar-benar punya isi approval_preview_pdf.
//
// Sumber file: utamakan PDF bertanda tangan dari Document Signing Log (mekanisme
// desk, versi ber-QR), jatuh ke approval_preview_pdf bila belum ada — file itu
// sudah tersimpan sehingga tidak perlu render wkhtmltopdf lagi.
const showPdf = computed(() => !!doc.data?.approval_preview_pdf)
const loadingPdf = ref(false)

// PdfViewer in-app (PDF.js), bukan window.open seperti desk: file signed ada di
// `/private/files` (butuh cookie session) dan endpoint render mengirim
// Content-Disposition attachment — keduanya cuma menghasilkan halaman kosong di
// WebView Android yang tak punya renderer PDF.
async function openDiskresiPdf() {
	if (loadingPdf.value) return
	loadingPdf.value = true
	try {
		let fileUrl = ''
		try {
			const params = new URLSearchParams({
				reference_doctype: 'Surat Diskresi',
				reference_name: name.value,
			})
			const res = await fetch(
				`/api/method/juragan.juragan.doctype.document_signing_log.document_signing_log.get_latest_signed_pdf?${params.toString()}`,
				{ method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } }
			)
			if (res.ok) fileUrl = (await res.json().catch(() => ({})))?.message || ''
		} catch (e) {
			// Signed PDF tak terjangkau → lanjut render live di bawah.
		}
		if (!fileUrl) fileUrl = doc.data?.approval_preview_pdf || ''
		if (!fileUrl) throw new Error('Dokumen ini belum punya file PDF.')
		openPdf(fileUrl, `Surat Diskresi ${name.value}`)
	} catch (e) {
		notifyError(e, 'Gagal membuka PDF')
	} finally {
		loadingPdf.value = false
	}
}

// ---- Workflow (Surat Diskresi Data Pengajuan) --------------------------------
const actionsOpen = ref(false)
const transitions = reactive({ loading: false, items: [], applying: '' })

// get_transitions mengembalikan transisi valid untuk role user (kolom Allowed +
// condition dievaluasi server — sama persis dengan desk). Workflow punya baris
// transisi DUPLIKAT (#8 & #9 = salinan #5 & #6 dari state Request Approval
// Ketua) → di-dedup berdasarkan action+next_state supaya tidak tampil dobel.
async function loadTransitions() {
	if (!doc.data) return
	transitions.loading = true
	try {
		const res = await fetch('/api/method/frappe.model.workflow.get_transitions', {
			method: 'POST',
			credentials: 'include',
			headers: {
				'Content-Type': 'application/json',
				Accept: 'application/json',
				'X-Frappe-CSRF-Token': window.csrf_token || '',
			},
			body: JSON.stringify({ doc: doc.data }),
		})
		const json = await res.json()
		const seen = new Set()
		transitions.items = (json.message || []).filter((t) => {
			const key = `${t.action}|${t.next_state}`
			if (seen.has(key)) return false
			seen.add(key)
			return true
		})
	} catch (e) {
		transitions.items = []
	} finally {
		transitions.loading = false
	}
}

async function applyAction(action) {
	transitions.applying = action
	banner.value = ''
	try {
		const res = await fetch('/api/method/frappe.model.workflow.apply_workflow', {
			method: 'POST',
			credentials: 'include',
			headers: {
				'Content-Type': 'application/json',
				Accept: 'application/json',
				'X-Frappe-CSRF-Token': window.csrf_token || '',
			},
			body: JSON.stringify({ doc: doc.data, action }),
		})
		const json = await res.json().catch(() => ({}))
		if (!res.ok) throw new Error(frappeError(json) || `HTTP ${res.status}`)
		actionsOpen.value = false
		await doc.fetch()
		syncFormFromDoc()
		loadTransitions()
		notifySuccess(`Aksi "${action}" berhasil diterapkan.`)
	} catch (e) {
		banner.value = e.message || String(e)
		actionsOpen.value = false
		notifyError(e, `Gagal menerapkan aksi "${action}"`)
	} finally {
		transitions.applying = ''
	}
}

onMounted(async () => {
	await refreshCsrfToken()
	loadMyRoles()
	await Promise.all([loadMeta(), doc.fetch()])
	syncFormFromDoc()
	loadTransitions()
})
</script>
